return [
  { json: { url: "https://t.me/s/Proxy_Qavi" } },
  { json: { url: "https://t.me/s/iMTProto" } },
  { json: { url: "https://t.me/s/iRoProxy" } },
  { json: { url: "https://t.me/s/TelMTProto" } },
  { json: { url: "https://t.me/s/ProxyMTProto" } },
  { json: { url: "https://t.me/s/Myporoxy" } },
  { json: { url: "https://t.me/s/ProxyHagh" } }
];

const items = $input.all();
const allProxies = [];

for (const item of items) {
  let html = '';
  if (typeof item.json?.data === 'string') html = item.json.data;
  else if (typeof item.json === 'string') html = item.json;
  else if (typeof item.json?.body === 'string') html = item.json.body;
  else html = JSON.stringify(item.json || '');

  // Recursively decode HTML entities (handles &amp;amp; from t.me/s pages)
  let prev;
  do {
    prev = html;
    html = html
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&#x2F;/g, '/');
  } while (html !== prev);

  // Collect proxy links (t.me/proxy and tg://proxy)
  const linkRegex = /(?:https?:\/\/t\.me\/|tg:\/\/)proxy\?[^\s<>"\']+/gi;
  const matches = html.match(linkRegex) || [];

  for (const link of matches) {
    // Regex-based param extraction (URL constructor is unavailable in the Code sandbox)
    const serverMatch = link.match(/[?&](?:server|ip)=([^&]+)/i);
    const portMatch = link.match(/[?&]port=([^&]+)/i);
    const secretMatch = link.match(/[?&](?:secret|pass)=([^&]+)/i);

    if (!serverMatch || !portMatch || !secretMatch) continue;

    const host = decodeURIComponent(serverMatch[1]);
    const port = parseInt(portMatch[1], 10);
    const secret = decodeURIComponent(secretMatch[1]);

    if (host && !isNaN(port) && port > 0 && secret) {
      allProxies.push({
        name: 'MTProto Proxy ' + host,
        host: host,
        port: port,
        secret: secret,
        location: 'درحال بررسی',
        flag: '🌐',
        country_code: 'ALL',
        is_active: true
      });
    }
  }
}

// Deduplicate by host:port
const uniqueProxies = [];
const seen = new Set();
for (const p of allProxies) {
  const key = p.host + ':' + p.port;
  if (!seen.has(key)) {
    seen.add(key);
    uniqueProxies.push(p);
  }
}

return [{
  json: {
    bulk: uniqueProxies,
    count: uniqueProxies.length
  }
}];
